print("Input grid:")
for row in input_grid:
    print(' '.join(str(x) for x in row))

# Find connected regions
def find_regions(grid):
    background = grid[0][0]
    visited = [[False] * len(grid[0]) for _ in range(len(grid))]
    regions = []

    for r in range(len(grid)):
        for c in range(len(grid[0])):
            if visited[r][c]:
                continue
            if grid[r][c] == background:
                continue

            color = grid[r][c]
            cells = []
            queue = [(r, c)]
            visited[r][c] = True

            while queue:
                cr, cc = queue.pop(0)
                cells.append((cr, cc))
                for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                    nr, nc = cr + dr, cc + dc
                    if 0 <= nr < len(grid) and 0 <= nc < len(grid[0]):
                        if not visited[nr][nc] and grid[nr][nc] == color:
                            visited[nr][nc] = True
                            queue.append((nr, nc))

            # Check if rectangular
            rs = sorted(set(cell[0] for cell in cells))
            cs = sorted(set(cell[1] for cell in cells))
            rect_cells = {(r, c) for r in rs for c in cs}

            if set(cells) == rect_cells:
                regions.append((rs[0], rs[-1], cs[0], cs[-1], color))

    return regions

regions = find_regions(input_grid)
print("\nRegions found:")
for region in regions:
